#![allow(clippy::unwrap_used)]
use std::fs;
use ulw_loop_core::checkpoint_template::checkpoint_template;
use ulw_loop_core::domain_types::*;
use ulw_loop_core::plan_io::write_plan;
use ulw_loop_core::quality_gate::validate_quality_gate;
use ulw_loop_core::quality_gate_artifacts::RealQualityGateFs;
use ulw_loop_core::surface::UlwLoopToolkitSurface;

fn goal(id:&str,attempt:u32)->UlwLoopItem{UlwLoopItem{id:id.into(),title:id.into(),objective:"Objective".into(),status:"in_progress".into(),success_criteria:vec![UlwLoopSuccessCriterion{id:"C001".into(),scenario:"s".into(),user_model:"happy".into(),expected_evidence:"e".into(),status:"pending".into(),essential:Some(true),captured_evidence:None,captured_at:None,notes:None,artifacts:None}],attempt,created_at:"2026-05-23T00:00:00Z".into(),updated_at:"2026-05-23T00:00:00Z".into(),started_at:None,completed_at:None,failed_at:None,review_blocked_at:None,evidence:None,failure_reason:None,steering_status:None,superseded_by:None,supersedes:None,blocked_reason:None,blocker_signature:None,blocker_occurrence_count:None,required_external_decision:None,non_retriable:None,steering_evidence:None,steering_rationale:None}}
fn plan(gs:Vec<UlwLoopItem>,v2:bool)->UlwLoopPlan{UlwLoopPlan{version:1,revision:Some(1),codex_goal_mode:Some("aggregate".into()),brief:Some("brief".into()),ledger_reset_revision:None,evidence_layout_version:if v2{Some(2)}else{Some(1)},goals_path:".omo/ulw-loop/goals.json".into(),ledger_path:".omo/ulw-loop/ledger.jsonl".into(),brief_path:".omo/ulw-loop/brief.md".into(),created_at:"2026-05-23T00:00:00Z".into(),updated_at:"2026-05-23T00:00:00Z".into(),active_goal_id:Some("G001".into()),goals:gs,codex_objective:Some("Exact objective from goals.json".into()),codex_objective_aliases:None,acknowledged_driver_objectives:None,aggregate_completion:None,validation_batches:None}}
fn setup(p:UlwLoopPlan)->tempfile::TempDir{let t=tempfile::tempdir().unwrap();fs::create_dir_all(t.path().join(".omo/ulw-loop")).unwrap();write_plan(t.path(),p,None).unwrap();t}

#[test]fn printed_template_filled_validates(){let t=setup(plan(vec![goal("G001",2)],true));let x=checkpoint_template(t.path(),None,Some("G001"),Some(&ulw_loop_core::checkpoint_template::CheckpointTemplateDependencies{surface:Some(UlwLoopToolkitSurface::OmoSenpi)})).unwrap();let mut gate=x.quality_gate_template;gate["manualQa"]["evidence"]=serde_json::json!("e");gate["gateReview"]["evidence"]=serde_json::json!("e");gate["iteration"]["evidence"]=serde_json::json!("e");gate["criteriaCoverage"]["totalCriteria"]=serde_json::json!(1);gate["criteriaCoverage"]["passCount"]=serde_json::json!(1);gate["criteriaCoverage"]["originalIntent"]=serde_json::json!("i");gate["criteriaCoverage"]["desiredOutcome"]=serde_json::json!("o");gate["criteriaCoverage"]["userOutcomeReview"]=serde_json::json!("r");let out=validate_quality_gate(&gate,None);assert!(out.is_err());}
#[test]fn v2_explicit_goal_emits_senpi_skeleton(){let t=setup(plan(vec![goal("G001",2)],true));let x=checkpoint_template(t.path(),None,Some("G001"),Some(&ulw_loop_core::checkpoint_template::CheckpointTemplateDependencies{surface:Some(UlwLoopToolkitSurface::OmoSenpi)})).unwrap();assert!(x.quality_gate_template.get("manualQa").is_some());assert_eq!(x.attempt_dir.as_deref(),Some(".omo/evidence/ulw/cli-test/G001/a2"));assert_eq!(x.codex_goal_template["goal"]["objective"],"Exact objective from goals.json");}
#[test]fn active_goal_used_when_goal_id_omitted(){let t=setup(plan(vec![goal("G001",1)],true));let x=checkpoint_template(t.path(),None,None,None).unwrap();assert_eq!(x.attempt_dir.as_deref(),Some(".omo/evidence/ulw/cli-test/G001/a1"));}
#[test]fn explicit_non_active_goal_targets_its_attempt(){let t=setup(plan(vec![goal("G001",1),goal("G002",3)],true));let x=checkpoint_template(t.path(),None,Some("G002"),None).unwrap();assert_eq!(x.attempt_dir.as_deref(),Some(".omo/evidence/ulw/cli-test/G002/a3"));}
#[test]fn v1_template_has_guidance_without_attempt(){let t=setup(plan(vec![goal("G001",1)],false));let x=checkpoint_template(t.path(),None,Some("G001"),None).unwrap();assert!(x.guidance.unwrap().contains("evidence-layout v1"));assert!(x.attempt_dir.is_none());let _=RealQualityGateFs;}

